-- 6. Menu Items (32 Items across all categories)
-- Category 1: Starters
INSERT INTO menu_items (id, category_id, name, slug, short_description, detailed_description, price, discounted_price, is_veg, is_vegan, is_gluten_free, spicy_level, calories, allergens, ingredients, preparation_time_minutes, is_available, is_bestseller, is_chef_special, is_new, rating, review_count, image_url) VALUES
('50000000-0000-0000-0000-000000000001', '40000000-0000-0000-0000-000000000001', 'Wood-Smoked Malai Paneer Tikka', 'wood-smoked-malai-paneer-tikka', 'Creamy cottage cheese infused with cardamom and smoked over cedarwood', 'Fresh farmhouse cottage cheese marinated for 12 hours in hung curd, green cardamom, roasted cumin, and white pepper, then finished over roaring cedar wood coals.', 380.00, 340.00, TRUE, FALSE, TRUE, 1, 420, '{"Dairy"}', '{"Paneer", "Hung Curd", "Cardamom", "Cashew Paste", "Charcoal Smoked Ghee"}', 18, TRUE, TRUE, FALSE, FALSE, 4.9, 148, 'https://images.unsplash.com/photo-1599488615731-7e5c2823ff28?w=800&auto=format&fit=crop&q=80'),
('50000000-0000-0000-0000-000000000002', '40000000-0000-0000-0000-000000000001', 'Flame-Charred Chipotle Wings', 'flame-charred-chipotle-wings', 'Crisp chicken wings glazed with smoked chipotle, honey, and toasted sesame', 'Free-range chicken wings slow roasted over hickory charcoal, then tossed in an intoxicating glaze of artisanal honey, chipotle adobo, garlic, and fresh lime.', 420.00, NULL, FALSE, FALSE, FALSE, 3, 510, '{"Sesame", "Soy"}', '{"Chicken Wings", "Chipotle Peppers", "Wild Honey", "Sesame", "Garlic Butter"}', 20, TRUE, TRUE, TRUE, FALSE, 4.8, 92, 'https://images.unsplash.com/photo-1567620832903-9fc6debc209f?w=800&auto=format&fit=crop&q=80'),
('50000000-0000-0000-0000-000000000003', '40000000-0000-0000-0000-000000000001', 'Truffle Parmesan Smoked Fries', 'truffle-parmesan-smoked-fries', 'Hand-cut russet potatoes dusted with aged parmesan, black truffle oil, and herbs', 'Double-fried hand-cut golden fries tossed with white truffle oil, sea salt, crackled rosemary, and a generous snow of 24-month aged Parmigiano Reggiano.', 290.00, 260.00, TRUE, FALSE, FALSE, 0, 380, '{"Dairy"}', '{"Russet Potatoes", "Truffle Oil", "Parmesan", "Rosemary", "Garlic Aioli"}', 15, TRUE, FALSE, FALSE, TRUE, 4.7, 64, 'https://images.unsplash.com/photo-1576107232684-1279f3908594?w=800&auto=format&fit=crop&q=80'),
('50000000-0000-0000-0000-000000000004', '40000000-0000-0000-0000-000000000001', 'Smoked Garlic Butter Prawns', 'smoked-garlic-butter-prawns', 'Jumbo sea prawns pan-roasted with charred garlic cloves, chili flakes, and sourdough', 'Succulent Arabian sea prawns seared in foaming garlic butter infused with applewood smoke, fresh flat-leaf parsley, and crushed red bird-eye chilies.', 560.00, NULL, FALSE, FALSE, FALSE, 2, 440, '{"Shellfish", "Dairy", "Gluten"}', '{"Jumbo Prawns", "Garlic Butter", "Bird Eye Chili", "Lemon", "Sourdough Toast"}', 18, TRUE, FALSE, TRUE, FALSE, 4.9, 78, 'https://images.unsplash.com/photo-1559742811-822873691df8?w=800&auto=format&fit=crop&q=80'),

-- Category 2: Folk & Flame Signatures
('50000000-0000-0000-0000-000000000005', '40000000-0000-0000-0000-000000000002', 'Charcoal Smoked Butter Chicken', 'charcoal-smoked-butter-chicken', 'Tandoor-charred chicken steeped in velvety sun-ripened tomato and smoked butter gravy', 'Our crown jewel. Free-range chicken thighs grilled in the tandoor, simmered in a velvety gravy of San Marzano tomatoes, cashew cream, dried fenugreek, and smoked live with a hot charcoal clove infusion.', 520.00, 480.00, FALSE, FALSE, TRUE, 1, 680, '{"Dairy", "Nuts"}', '{"Tandoori Chicken", "Tomatoes", "Smoked Butter", "Cashew Gravy", "Kasuri Methi"}', 25, TRUE, TRUE, TRUE, FALSE, 5.0, 312, 'https://images.unsplash.com/photo-1588166524941-3bf61a9c41db?w=800&auto=format&fit=crop&q=80'),
('50000000-0000-0000-0000-000000000006', '40000000-0000-0000-0000-000000000002', '12-Hour Hickory Smoked Dal Makhani', '12-hour-hickory-smoked-dal-makhani', 'Black urad lentils slow-simmered over dying ember fires with white butter and cream', 'Black lentils and red kidney beans simmered continuously for 12 hours over fragrant sal wood embers, enriched with churned country butter and cold-pressed mustard oil smoke.', 390.00, 360.00, TRUE, FALSE, TRUE, 1, 480, '{"Dairy"}', '{"Black Lentils", "White Butter", "Heavy Cream", "Slow-Roasted Tomatoes", "Fenugreek"}', 20, TRUE, TRUE, FALSE, FALSE, 4.9, 215, 'https://images.unsplash.com/photo-1546833999-b9f581a1996d?w=800&auto=format&fit=crop&q=80'),
('50000000-0000-0000-0000-000000000007', '40000000-0000-0000-0000-000000000002', 'Flame-Grilled Atlantic Salmon', 'flame-grilled-atlantic-salmon', 'Norwegian salmon fillet with charred lemon herb crust and wild mushroom risotto', 'Sustainably sourced salmon seared directly on cast iron grills over fruitwood flames, glazed with Dijon mustard, honey, and fresh dill, served over creamy wild mushroom arborio rice.', 780.00, NULL, FALSE, FALSE, TRUE, 1, 590, '{"Fish", "Dairy"}', '{"Atlantic Salmon", "Wild Mushrooms", "Arborio Rice", "Charred Lemon", "Dill Butter"}', 25, TRUE, FALSE, TRUE, TRUE, 4.8, 59, 'https://images.unsplash.com/photo-1467003909585-2f8a72700288?w=800&auto=format&fit=crop&q=80'),
('50000000-0000-0000-0000-000000000008', '40000000-0000-0000-0000-000000000002', 'Slow-Braised Nihari Gosht', 'slow-braised-nihari-gosht', 'Tender lamb shank stewed overnight in a fragrant 32-spice broth with bone marrow', 'Melt-in-the-mouth shank of pasture-raised lamb slow cooked for 8 hours with caramelized onions, star anise, mace, and long pepper. Topped with julienned ginger and fresh lime.', 640.00, 590.00, FALSE, FALSE, TRUE, 2, 720, '{}', '{"Lamb Shank", "Bone Marrow", "Caramelized Onions", "Nihari Spices", "Kewra Water"}', 22, TRUE, TRUE, TRUE, FALSE, 4.9, 134, 'https://images.unsplash.com/photo-1545247181-516773ca838b?w=800&auto=format&fit=crop&q=80'),

-- Category 3: Live Grills & Kebabs
('50000000-0000-0000-0000-000000000009', '40000000-0000-0000-0000-000000000003', 'Angaar Mutton Seekh Kebab', 'angaar-mutton-seekh-kebab', 'Hand-minced prime mutton seasoned with raw papaya, mint, and flame embers', 'Prime goat mince kneaded with marrow fat, roasted coriander seeds, green chilies, and smoked clove butter, skewered and roasted to juicy perfection in our charcoal pit.', 540.00, NULL, FALSE, FALSE, TRUE, 3, 560, '{"Dairy"}', '{"Minced Mutton", "Mint Chutney", "Roasted Spices", "Ghee", "Pickled Onions"}', 20, TRUE, TRUE, FALSE, FALSE, 4.8, 118, 'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?w=800&auto=format&fit=crop&q=80'),
('50000000-0000-0000-0000-000000000010', '40000000-0000-0000-0000-000000000003', 'Dahi Ke Sholay & Kebab', 'dahi-ke-sholay-kebab', 'Crispy spiced yogurt patties with pomegranate pearls and roasted cumin sauce', 'Silken hung curd infused with crushed black pepper, fresh coriander, ginger, and aged cottage cheese, enveloped in a delicate crust and quickly pan-charred with ghee.', 360.00, 320.00, TRUE, FALSE, FALSE, 1, 390, '{"Dairy", "Gluten"}', '{"Hung Curd", "Pomegranate", "Green Chilies", "Roasted Cumin", "Mint Relish"}', 16, TRUE, FALSE, TRUE, FALSE, 4.7, 85, 'https://images.unsplash.com/photo-1601050690597-df0568f70950?w=800&auto=format&fit=crop&q=80'),
('50000000-0000-0000-0000-000000000011', '40000000-0000-0000-0000-000000000003', 'Kasundi Mustard Charred Fish Tikka', 'kasundi-mustard-charred-fish-tikka', 'Bengal bhetki fish steaks marinated in raw mango mustard and cold-pressed oil', 'Fresh water Bhetki fillets coated in fiery Kolkata Kasundi mustard, turmeric, and lime, grilled over high charcoal heat for a smoky, tender bite.', 530.00, NULL, FALSE, FALSE, TRUE, 2, 410, '{"Fish", "Mustard"}', '{"Bhetki Fish", "Kasundi Mustard", "Raw Mango Paste", "Mustard Oil", "Nigella Seeds"}', 18, TRUE, FALSE, FALSE, TRUE, 4.8, 49, 'https://images.unsplash.com/photo-1534422298391-e4f8c172dddb?w=800&auto=format&fit=crop&q=80'),
('50000000-0000-0000-0000-000000000012', '40000000-0000-0000-0000-000000000003', 'Tandoori Smoked Portobello Caps', 'tandoori-smoked-portobello-caps', 'Thick portobello mushrooms stuffed with herbed goat cheese and flame roasted', 'Giant portobello caps stuffed with local Chevre cheese, smoked garlic, walnuts, and fine herbs, char-grilled with smoked paprika butter.', 410.00, NULL, TRUE, FALSE, FALSE, 1, 340, '{"Dairy", "Nuts"}', '{"Portobello Mushrooms", "Goat Cheese", "Walnuts", "Smoked Paprika", "Herb Pesto"}', 18, TRUE, FALSE, TRUE, TRUE, 4.9, 52, 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=800&auto=format&fit=crop&q=80'),

-- Category 4: Artisanal Dum Biryanis
('50000000-0000-0000-0000-000000000013', '40000000-0000-0000-0000-000000000004', 'Awadhi Flame Dum Chicken Biryani', 'awadhi-flame-dum-chicken-biryani', 'Aged Daawat basmati, tender chicken thighs, saffron milk, and rose petal smoke', 'Layered in heavy earthen pots sealed with whole wheat dough and cooked over charcoal ash for 45 minutes. Infused with pure Kashmiri saffron, itar, and crispy fried shallots.', 480.00, 440.00, FALSE, FALSE, TRUE, 2, 750, '{"Dairy"}', '{"Basmati Rice", "Chicken Thighs", "Kashmiri Saffron", "Ghee", "Fried Onions", "Mint"}', 25, TRUE, TRUE, TRUE, FALSE, 4.9, 290, 'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?w=800&auto=format&fit=crop&q=80'),
('50000000-0000-0000-0000-000000000014', '40000000-0000-0000-0000-000000000004', 'Nizam-e-Khas Mutton Dum Biryani', 'nizam-e-khas-mutton-dum-biryani', 'Succulent prime mutton marinated in raw papaya and cooked on dum with aged rice', 'Tender cuts of goat meat marinated in house blend garam masala, yogurt, and mint, gently steamed under a charcoal lid seal with whole spices.', 590.00, 540.00, FALSE, FALSE, TRUE, 3, 840, '{"Dairy"}', '{"Prime Mutton", "Aged Basmati", "Shahi Zeera", "Pure Cow Ghee", "Biryani Spices"}', 30, TRUE, TRUE, FALSE, FALSE, 5.0, 187, 'https://images.unsplash.com/photo-1633945274405-b6c8069047b0?w=800&auto=format&fit=crop&q=80'),
('50000000-0000-0000-0000-000000000015', '40000000-0000-0000-0000-000000000004', 'Smoked Saffron Subz Dum Biryani', 'smoked-saffron-subz-dum-biryani', 'Garden vegetables, baby carrots, green peas, and paneer with saffron-infused rice', 'Seasonal heritage vegetables and golden paneer cubes simmered in aromatic gravy and dum-cooked with fragrant extra-long basmati rice, served with smoked burani raita.', 390.00, 350.00, TRUE, FALSE, TRUE, 1, 560, '{"Dairy"}', '{"Baby Carrots", "Green Peas", "Paneer", "Basmati Rice", "Saffron Milk", "Mint"}', 22, TRUE, FALSE, FALSE, FALSE, 4.8, 114, 'https://images.unsplash.com/photo-1589302168068-964664d93dc0?w=800&auto=format&fit=crop&q=80'),
('50000000-0000-0000-0000-000000000016', '40000000-0000-0000-0000-000000000004', 'Burnt Garlic Jasmine Rice & Truffle', 'burnt-garlic-jasmine-rice-truffle', 'Fragrant jasmine rice wok-tossed with charred golden garlic and truffle oil', 'Steamed Thai jasmine rice flash-tossed in a flaming wok with golden crisp garlic chips, scallions, cold-pressed sesame oil, and French black truffle essence.', 340.00, NULL, TRUE, TRUE, TRUE, 1, 390, '{"Sesame"}', '{"Jasmine Rice", "Golden Garlic", "Truffle Oil", "Scallions", "Toasted Sesame"}', 15, TRUE, FALSE, TRUE, TRUE, 4.7, 46, 'https://images.unsplash.com/photo-1512058564366-18510be2db19?w=800&auto=format&fit=crop&q=80'),

-- Category 5: Wood-Fired Burgers & Sandwiches
('50000000-0000-0000-0000-000000000017', '40000000-0000-0000-0000-000000000005', 'The Folk Beast Burger', 'the-folk-beast-burger', 'Double smashed smoked mutton patty, cheddar, bacon jam, and charred onion aioli', 'Two 100g coarse-ground mutton patties flame seared on cast iron, melted double vintage cheddar, sweet bacon-onion jam, and secret burnt chili aioli in toasted brioche.', 490.00, 450.00, FALSE, FALSE, FALSE, 2, 850, '{"Gluten", "Dairy", "Egg"}', '{"Prime Mutton Patty", "Aged Cheddar", "Brioche Bun", "Bacon Jam", "Smoked Aioli"}', 18, TRUE, TRUE, TRUE, FALSE, 4.9, 162, 'https://images.unsplash.com/photo-1568901346375-23c9450c58cd?w=800&auto=format&fit=crop&q=80'),
('50000000-0000-0000-0000-000000000018', '40000000-0000-0000-0000-000000000005', 'Fiery Flame Crispy Chicken Burger', 'fiery-flame-crispy-chicken-burger', 'Buttermilk fried chicken breast dipped in Nashville hot oil with dill pickles', 'Buttermilk soaked chicken thigh fried until ultra-crisp, immediately dipped into our signature flaming paprika chili oil, topped with pickled cucumber slaw and garlic mayo.', 420.00, 380.00, FALSE, FALSE, FALSE, 3, 760, '{"Gluten", "Dairy", "Egg"}', '{"Fried Chicken", "Nashville Hot Oil", "Pickles", "Brioche Bun", "Garlic Mayo"}', 18, TRUE, TRUE, FALSE, FALSE, 4.8, 126, 'https://images.unsplash.com/photo-1625813506062-0aeb1d7a094b?w=800&auto=format&fit=crop&q=80'),
('50000000-0000-0000-0000-000000000019', '40000000-0000-0000-0000-000000000005', 'Charred Halloumi & Avocado Burger', 'charred-halloumi-avocado-burger', 'Thick grilled Cypriot halloumi, smashed avocado, roast bell pepper, and pesto', 'Golden charred halloumi cheese slab, creamy Hass avocado guacamole, fire-roasted sweet bell peppers, and arugula pesto served in an artisanal multigrain bun.', 410.00, NULL, TRUE, FALSE, FALSE, 1, 620, '{"Gluten", "Dairy"}', '{"Halloumi", "Hass Avocado", "Roasted Bell Peppers", "Arugula Pesto", "Multigrain Bun"}', 16, TRUE, FALSE, TRUE, TRUE, 4.7, 73, 'https://images.unsplash.com/photo-1550547660-d9450f859349?w=800&auto=format&fit=crop&q=80'),
('50000000-0000-0000-0000-000000000020', '40000000-0000-0000-0000-000000000005', 'Smoked Pulled Lamb Panini', 'smoked-pulled-lamb-panini', '8-hour wood-smoked pulled lamb shoulder, smoked mozzarella, and caramelized onions', 'Crusty artisan ciabatta bread pressed with juicy tender pulled lamb, melted smoked mozzarella, fresh mint pesto, and balsamic caramelized red onions.', 460.00, NULL, FALSE, FALSE, FALSE, 1, 690, '{"Gluten", "Dairy"}', '{"Pulled Lamb", "Ciabatta", "Smoked Mozzarella", "Caramelized Onions", "Mint Pesto"}', 16, TRUE, FALSE, FALSE, FALSE, 4.8, 54, 'https://images.unsplash.com/photo-1528735602780-2552fd46c7af?w=800&auto=format&fit=crop&q=80'),

-- Category 6: Flame-Baked Artisan Pizzas
('50000000-0000-0000-0000-000000000021', '40000000-0000-0000-0000-000000000006', 'Burnt Truffle & Wild Mushroom Pizza', 'burnt-truffle-wild-mushroom-pizza', 'Charred wild shimeji, portobello, fior di latte, truffle cream, and thyme', 'Hand-stretched sourdough baked at 450°C in our wood oven. Creamy white truffle base, sautéed wild mushrooms, fresh thyme, fior di latte mozzarella, and shaved parmesan.', 580.00, 520.00, TRUE, FALSE, FALSE, 0, 780, '{"Gluten", "Dairy"}', '{"Wild Mushrooms", "Truffle Cream", "Fior di Latte", "Thyme", "Sourdough Crust"}', 20, TRUE, TRUE, TRUE, FALSE, 4.9, 142, 'https://images.unsplash.com/photo-1513104890138-7c749659a591?w=800&auto=format&fit=crop&q=80'),
('50000000-0000-0000-0000-000000000022', '40000000-0000-0000-0000-000000000006', 'Charred Pepperoni & Hot Honey Pizza', 'charred-pepperoni-hot-honey-pizza', 'Crispy cupping pepperoni, San Marzano tomato sauce, fior di latte, and hot chili honey', 'Imported artisanal smoked pepperoni cups crisped under wood fire flames, topped with fresh mozzarella, basil, and a generous drizzle of spicy habanero hot honey.', 620.00, 570.00, FALSE, FALSE, FALSE, 2, 890, '{"Gluten", "Dairy"}', '{"Pepperoni", "Hot Honey", "San Marzano Tomatoes", "Mozzarella", "Fresh Basil"}', 18, TRUE, TRUE, FALSE, FALSE, 5.0, 189, 'https://images.unsplash.com/photo-1628840042765-356cda07504e?w=800&auto=format&fit=crop&q=80'),
('50000000-0000-0000-0000-000000000023', '40000000-0000-0000-0000-000000000006', 'Smoked Margherita di Bufala', 'smoked-margherita-di-bufala', 'Smoked campania buffalo mozzarella, sweet cherry tomatoes, and sweet basil', 'The quintessential classic elevated with subtle wood smoke. Campania buffalo mozzarella, crushed sweet Italian tomatoes, sea salt, extra virgin olive oil, and wood-torched basil.', 480.00, 430.00, TRUE, FALSE, FALSE, 0, 710, '{"Gluten", "Dairy"}', '{"Buffalo Mozzarella", "Cherry Tomatoes", "Basil", "Olive Oil", "Sourdough"}', 18, TRUE, FALSE, FALSE, FALSE, 4.8, 98, 'https://images.unsplash.com/photo-1604382354936-07c5d9983bd3?w=800&auto=format&fit=crop&q=80'),
('50000000-0000-0000-0000-000000000024', '40000000-0000-0000-0000-000000000006', 'Flame Tikka Chicken Pizza', 'flame-tikka-chicken-pizza', 'Tandoor-charred chicken tikka, pickled red onions, coriander, and mozzarella', 'A fusion marvel. Wood-fired pizza dough topped with makhani reduction sauce, smoky chicken tikka pieces, charred bell peppers, mozzarella, and drizzle of mint sour cream.', 560.00, NULL, FALSE, FALSE, FALSE, 2, 820, '{"Gluten", "Dairy"}', '{"Chicken Tikka", "Makhani Sauce", "Mozzarella", "Pickled Onions", "Mint Cream"}', 20, TRUE, FALSE, TRUE, TRUE, 4.9, 105, 'https://images.unsplash.com/photo-1593560708920-61dd98c46a4e?w=800&auto=format&fit=crop&q=80'),

-- Category 7: Flame-Finished Desserts
('50000000-0000-0000-0000-000000000025', '40000000-0000-0000-0000-000000000007', 'Smoked Bourbon Chocolate Fondant', 'smoked-bourbon-chocolate-fondant', 'Molten 70% dark Belgian chocolate lava cake infused with Kentucky bourbon smoke', 'Warm chocolate fondant with a flowing molten core of single-origin dark chocolate, spiked with Kentucky bourbon reduction, served with homemade burnt vanilla ice cream.', 360.00, 320.00, TRUE, FALSE, FALSE, 0, 520, '{"Dairy", "Egg", "Gluten"}', '{"Belgian Dark Chocolate", "Bourbon", "Madagascar Vanilla", "Farm Eggs", "Butter"}', 18, TRUE, TRUE, TRUE, FALSE, 5.0, 178, 'https://images.unsplash.com/photo-1606313564200-e75d5e30476c?w=800&auto=format&fit=crop&q=80'),
('50000000-0000-0000-0000-000000000026', '40000000-0000-0000-0000-000000000007', 'Flame-Torched Smores Skillet', 'flame-torched-smores-skillet', 'Gooey marshmallows toasted with open torch over graham cracker crumble and fudge', 'Served in a sizzling hot cast iron skillet. Decadent layer of chocolate fudge, artisanal biscuit crumble, and house-made vanilla marshmallows torched table-side.', 320.00, NULL, TRUE, FALSE, FALSE, 0, 480, '{"Dairy", "Gluten"}', '{"Marshmallows", "Chocolate Fudge", "Graham Biscuit", "Sea Salt"}', 15, TRUE, FALSE, FALSE, TRUE, 4.8, 67, 'https://images.unsplash.com/photo-1541781774459-bb2af2f05b55?w=800&auto=format&fit=crop&q=80'),
('50000000-0000-0000-0000-000000000027', '40000000-0000-0000-0000-000000000007', 'Saffron Malai Tres Leches', 'saffron-malai-tres-leches', 'Ultra-light sponge cake soaked in saffron, cardamom, and condensed milk cream', 'Classic Mexican tres leches reimagined with royal Indian flavors. Moist sponge cake drenched in saffron-infused three milks, crowned with pistachio slivers and edible silver foil.', 340.00, 299.00, TRUE, FALSE, FALSE, 0, 440, '{"Dairy", "Gluten", "Nuts"}', '{"Saffron", "Cardamom", "Condensed Milk", "Sponge Cake", "Pistachios"}', 12, TRUE, TRUE, FALSE, FALSE, 4.9, 131, 'https://images.unsplash.com/photo-1578985545062-69928b1d9587?w=800&auto=format&fit=crop&q=80'),
('50000000-0000-0000-0000-000000000028', '40000000-0000-0000-0000-000000000007', 'Wood-Fired Caramelized Apple Tart', 'wood-fired-caramelized-apple-tart', 'Thinly sliced crisp apples caramelized on puff pastry in wood oven with cinnamon', 'Flaky French puff pastry layered with thin honeycrisp apples, dark muscovado sugar, and Saigon cinnamon, baked till golden-crisp and served with salted caramel drizzle.', 310.00, NULL, TRUE, FALSE, FALSE, 0, 410, '{"Dairy", "Gluten"}', '{"Honeycrisp Apples", "Puff Pastry", "Muscovado Sugar", "Cinnamon", "Salted Caramel"}', 18, TRUE, FALSE, TRUE, FALSE, 4.7, 43, 'https://images.unsplash.com/photo-1535141192574-5d4897c13136?w=800&auto=format&fit=crop&q=80'),

-- Category 8: Handcrafted Elixirs
('50000000-0000-0000-0000-000000000029', '40000000-0000-0000-0000-000000000008', 'Smoked Rosemary Old Fashioned Mocktail', 'smoked-rosemary-old-fashioned-mocktail', 'Charred sprigs of fresh rosemary, spiced demerara cordial, bitters, and orange peel', 'Non-alcoholic zero-proof craftsmanship. Smoked live under a glass cloche with fresh rosemary embers, non-alcoholic botanicals, aromatic bitters, and a large crystal ice sphere.', 260.00, 220.00, TRUE, TRUE, TRUE, 0, 110, '{}', '{"Fresh Rosemary Smoke", "Demerara Syrup", "Botanical Bitters", "Charred Orange"}', 10, TRUE, TRUE, TRUE, FALSE, 4.9, 112, 'https://images.unsplash.com/photo-1551024709-8f23befc6f87?w=800&auto=format&fit=crop&q=80'),
('50000000-0000-0000-0000-000000000030', '40000000-0000-0000-0000-000000000008', 'Burnt Orange Ginger Fizz', 'burnt-orange-ginger-fizz', 'Caramelized Valencia oranges, spicy pressed ginger juice, and sparkling soda', 'Flame-broiled orange juice shaken with cold-pressed organic ginger, crushed mint sprigs, lime, and effervescent sparkling tonic water.', 220.00, NULL, TRUE, TRUE, TRUE, 1, 95, '{}', '{"Burnt Orange Juice", "Fresh Ginger", "Mint", "Lime", "Sparkling Water"}', 8, TRUE, FALSE, FALSE, TRUE, 4.8, 62, 'https://images.unsplash.com/photo-1513558161293-cdaf765ed2fd?w=800&auto=format&fit=crop&q=80'),
('50000000-0000-0000-0000-000000000031', '40000000-0000-0000-0000-000000000008', 'Flame-Chilled Kokum Cold Brew', 'flame-chilled-kokum-cold-brew', 'Chikmagalur Arabica 18-hr cold brew blended with tangy Konkan kokum fruit syrup', 'Single-estate coffee beans steeped cold for 18 hours, layered with indigenous Konkan kokum syrup, rock salt, and toasted cumin dust over ice.', 240.00, NULL, TRUE, TRUE, TRUE, 0, 80, '{}', '{"Arabica Cold Brew", "Konkan Kokum", "Rock Salt", "Cumin Dust", "Sparkling Soda"}', 8, TRUE, FALSE, TRUE, FALSE, 4.7, 51, 'https://images.unsplash.com/photo-1517701604599-bb29b565090c?w=800&auto=format&fit=crop&q=80'),
('50000000-0000-0000-0000-000000000032', '40000000-0000-0000-0000-000000000008', 'Spiced Kashmiri Kahwa', 'spiced-kashmiri-kahwa', 'Green tea infused with whole saffron strands, cinnamon bark, and roasted almond slivers', 'Traditional brass samovar brewed green tea enriched with genuine Kashmiri saffron strands, green cardamom, cinnamon quills, and crushed roasted almonds.', 210.00, 180.00, TRUE, TRUE, TRUE, 0, 60, '{"Nuts"}', '{"Green Tea", "Kashmiri Saffron", "Cinnamon", "Cardamom", "Crushed Almonds"}', 8, TRUE, TRUE, FALSE, FALSE, 4.9, 93, 'https://images.unsplash.com/photo-1576092768241-dec231879fc3?w=800&auto=format&fit=crop&q=80')
ON CONFLICT (slug) DO NOTHING;

