INSERT INTO reviews (user_id, menu_item_id, food_rating, service_rating, delivery_rating, comment, customer_name, is_moderated) VALUES
('10000000-0000-0000-0000-000000000003', '50000000-0000-0000-0000-000000000005', 5, 5, 5, 'The charcoal smoke in the butter chicken is out of this world! Best I have ever had anywhere in Mumbai.', 'Aarav Patel', TRUE),
('10000000-0000-0000-0000-000000000003', '50000000-0000-0000-0000-000000000017', 5, 4, 5, 'The Folk Beast Burger has unmatched smoky flavor and juicy beef patties. The brioche was fresh and warm.', 'Priya Menon', TRUE),
('10000000-0000-0000-0000-000000000003', '50000000-0000-0000-0000-000000000021', 5, 5, 4, 'Wood-fired crust with real leopard spotting. The wild mushrooms and truffle cream are pure luxury.', 'Devendra Verma', TRUE)
